import os
import subprocess
import stat

# Function to find the script directory
def get_script_dir():
    return os.path.dirname(os.path.abspath(__file__))

# Function to find the Amibian folder
def find_amibian_folder():
    script_dir = get_script_dir()
    while True:
        if os.path.basename(script_dir) == "Amibian":
            return script_dir
        parent_dir = os.path.dirname(script_dir)
        if parent_dir == script_dir:
            raise FileNotFoundError("Amibian folder not found.")
        script_dir = parent_dir

# Function to read the configuration file
def read_configuration():
    amibian_folder = find_amibian_folder()
    config_path = os.path.join(amibian_folder, "config", "amibian.configuration")
    config = {}
    with open(config_path, 'r') as file:
        for line in file:
            if '=' in line:
                key, value = line.strip().split('=', 1)
                config[key] = value
    return config

# Function to check if Amibian is installed
def check_installation():
    config = read_configuration()
    if config.get('installed') == 'no':
        if messagebox.askyesno("Install Amibian", "Amibian is not installed. Do you want to install?"):
            amibian_folder = find_amibian_folder()
            install_script = os.path.join(amibian_folder, "shells", "install.sh")
            subprocess.run(["bash", install_script])
            config['installed'] = 'yes'
            write_configuration(config)
        else:
            messagebox.showinfo("Goodbye", "Alrighty then, bye bye!")
            root.destroy()
            return False
    return True

# Function to write the configuration file
def write_configuration(new_config):
    amibian_folder = find_amibian_folder()
    config_path = os.path.join(amibian_folder, "config", "amibian.configuration")
    
    # Read the existing configuration
    existing_config = {}
    if os.path.exists(config_path):
        with open(config_path, 'r') as file:
            for line in file:
                if '=' in line:
                    key, value = line.strip().split('=', 1)
                    existing_config[key] = value
    
    # Update the existing configuration with new values
    existing_config.update(new_config)
    
    # Write the updated configuration back to the file
    with open(config_path, 'w') as file:
        for key, value in existing_config.items():
            file.write(f"{key}={value}\n")

