# Function to check for internet connection
def check_internet_connection():
    try:
        subprocess.check_call(["ping", "-c", "1", "github.com"])
        return True
    except subprocess.CalledProcessError:
        return False

# Function to get the current version from the configuration file
def get_current_version():
    amibian_folder = find_amibian_folder()
    config_file_path = os.path.join(amibian_folder, "config", "amibian_version")
    with open(config_file_path, "r") as file:
        for line in file:
            if line.startswith("amibian_"):
                return line.split("_")[1].strip()

# Function to update the project from GitHub
def update_project():
    amibian_folder = find_amibian_folder()
    os.chdir(amibian_folder)
    if not check_internet_connection():
        show_no_internet_message()
        return

    result = subprocess.run(["git", "pull"], capture_output=True, text=True)
    if "Already" in result.stdout:
        version = get_current_version()
        show_no_update_message(version)
    else:
        show_update_available_message()

def show_no_update_message(version):
    no_update_image_path = os.path.join(find_amibian_folder(), "graphics", "misc_icons", "no_update.png")
    no_update_window = tk.Toplevel(root)
    no_update_window.title("No Update Available")

    img = tk.PhotoImage(file=no_update_image_path)
    img_label = tk.Label(no_update_window, image=img)
    img_label.image = img
    img_label.pack(pady=10)

    text_label = tk.Label(no_update_window, text=f"Already up to date, Amibian {version}", font=("Helvetica", 12))
    text_label.pack(pady=10)

    def close_no_update_message():
        no_update_window.destroy()

    ok_button = tk.Button(no_update_window, text="OK", command=close_no_update_message)
    ok_button.pack(pady=10)

    no_update_window.mainloop()

