def run_update_script():
    amibian_folder = find_amibian_folder()
    update_script_path = os.path.join(amibian_folder, "shells", "update.sh")
    subprocess.run(["bash", update_script_path])
    version = get_current_version()
    messagebox.showinfo("Update", f"Amibian updated, Amibian {version}")

# Function to handle the "GPIO" button click
def open_gpio_menu(parent_window):
    parent_window.withdraw()
    gpio_window = tk.Toplevel(root)
    gpio_window.title("GPIO Menu")
    gpio_window.geometry("680x420")

    def close_gpio_menu():
        gpio_window.destroy()
        parent_window.deiconify()

    # Create a label for the GPIO menu
    label = tk.Label(gpio_window, text="GPIO Menu", font=("Helvetica", 18))
    label.pack(pady=10)

    # Create a frame for the GPIO inputs
    gpio_frame = tk.Frame(gpio_window)
    gpio_frame.pack(pady=10)
    
    # Function to locate the image file
    def get_image_path():
        script_dir = os.path.dirname(os.path.abspath(__file__))
        return os.path.join(script_dir, '..', 'graphics', 'amibian_logo', 'Amibian.png')
        
    # Add the image to the image frame
    image_path = get_image_path()
    img = tk.PhotoImage(file=image_path)
    img_label = tk.Label(gpio_window, image=img)
    img_label.image = img  # Keep a reference to avoid garbage collection
    img_label.place(relx=1.0, y=210, anchor="ne", x=-10)

    # Function to create a switch
    def create_switch(frame, row, config_key):
        switch_var = tk.StringVar(value=config.get(config_key, "off"))
        switch = tk.Checkbutton(frame, text="", variable=switch_var, onvalue="on", offvalue="off")
        switch.grid(row=row, column=1, padx=5, pady=5)
        return switch_var

    # Function to create a GPIO pin entry
    def create_gpio_entry(frame, row, config_key, column):
        gpio_entry = tk.Entry(frame, width=10)
        gpio_entry.grid(row=row, column=column, padx=5, pady=5)
        gpio_entry.insert(0, config.get(config_key, ""))
        return gpio_entry

    # Function to create a trigger dropdown
    def create_trigger_dropdown(frame, row, config_key):
        trigger_var = tk.StringVar(value=config.get(config_key, ""))
        trigger_dropdown = tk.OptionMenu(frame, trigger_var, "cpu", "blink", "heartbeat", "on")
        trigger_dropdown.grid(row=row, column=3, padx=5, pady=5)
        return trigger_var

    # Read the current configuration
    config = read_configuration()

    # Create the rows for each GPIO option
    options = [
        ("Power Led", "power_led_status", "power_led_pin", "power_led_trigger"),
        ("Amibian Launcher / Game Led", "game_led_status", "game_led_pin", "game_led_trigger"),
        ("SD Card Activity Led", "activity_led_status", "activity_led_pin", None),
        ("USB Flashdrive Activity LED", "usb_activity_status", None, None),
        ("Caps Lock Led", "capslock_led_status", "capslock_led_pin", None),
        ("Num Lock Led", "numlock_led_status", "numlock_led_pin", None),
        ("Scroll Lock Led", "scrlock_led_status", "scrlock_led_pin", None),
        ("Power Button", "power_button_status", "power_button_pin", None)
    ]

    switch_vars = {}
    gpio_entries = {}
    trigger_vars = {}

    for i, (description, status_key, pin_key, trigger_key) in enumerate(options):
        tk.Label(gpio_frame, text=description).grid(row=i, column=0, padx=5, pady=5, sticky="e")
        switch_vars[status_key] = create_switch(gpio_frame, i, status_key)
        if pin_key:
            gpio_entries[pin_key] = create_gpio_entry(gpio_frame, i, pin_key, column=2)
            if description == "Power Button":
                gpio_entries[pin_key].config(state="readonly")
        if trigger_key:
            trigger_vars[trigger_key] = create_trigger_dropdown(gpio_frame, i, trigger_key)
        if description == "USB Flashdrive Activity LED":
            for j in range(4):
                gpio_entries[f"usb_activity_pin{j+1}"] = create_gpio_entry(gpio_frame, i, f"usb_activity_pin{j+1}", column=2+j)
              
    # Create a frame for the back, home, exit, help, and set config buttons
    button_frame = tk.Frame(gpio_window)
    button_frame.pack(pady=20, anchor="w")

    # Create the "Back" button
    back_button = tk.Button(button_frame, text="Back", command=close_gpio_menu)
    back_button.pack(side="left", padx=10)

    # Create the "Home" button
    home_button = tk.Button(button_frame, text="Home", command=lambda: close_all_windows())
    home_button.pack(side="left", padx=10)

    # Create the "Exit" button
    exit_button = tk.Button(button_frame, text="Exit", command=root.destroy)
    exit_button.pack(side="left", padx=10)

    # Create the "Help" button
    def show_help():
        help_window = tk.Toplevel(gpio_window)
        help_window.title("GPIO Help")
        help_window.geometry("840x930")

        def show_help_image():
            help_image_window = tk.Toplevel(help_window)
            help_image_window.title("Connecting to the GPIO")
            help_image_window.geometry("1080x900")

            help_image = tk.PhotoImage(file=os.path.join(find_amibian_folder(), "graphics", "help", "help.png"))
            image_label = tk.Label(help_image_window, image=help_image)
            image_label.image = help_image
            image_label.pack(pady=10)

            def close_help_image():
                help_image_window.destroy()

            def back_to_help_text():
                help_image_window.destroy()
                show_help()

            # Create buttons for the help image window
            button_frame = tk.Frame(help_image_window)
            button_frame.pack(pady=10)

            exit_button = tk.Button(button_frame, text="Close", command=close_help_image)
            exit_button.pack(side="left", padx=10)

        label = tk.Label(help_window, text="Tick a box to turn a feature on, untick to turn off,\n \nDo not turn on a feature that you do not intend to use \n \nMake sure that the pin you have selected is correctly connected before turning a feature on. \n \nAfter making the changes you need, press the set configuration button \nfor changes to be set, some changes may require a reboot before they start working,\n \nThere are 40 Pins on a Rasperry Pi \n2 are 5v Pins,        \n2 are 3.3v Pins,     \n8 are ground Pins, \n28 are GPIO Pins,     \nthey are numbered from 0 to 27,\nbut not all of them are availible to use here. \n \nPin 0 and pin 1 are reserved for EEPROM data, \nin some cases, using those pins for regular output is ok, but it is excluded to be safe. \n pin3 is the default for a power switch. \n \nFor the power LED and game LED, you can select effects, \n \nCPU=   LED brightness depends on cpu usage. \nBlink=   LED blinks                                               \nHeartbeat=   LED blinks like a heartbeat.                            \nOn=   LED stays on                                       \n \nGame LED works with the Amibian launcher creator,\nRunning applications or games with a launcher made in the Amibian launcher creator \ngives an option to turn on a LED while the game or application is running\n \nUSB activity LED - Amibian detects activity on uptoo 4 seperate flashdrives,\nbut it is not needed to use 4 LEDs, only assign a pin number as you need, \nif 1 pin is assigned all activity on the flashdrives are indicated on the 1 LED\nif 2 pins are assigned, then 2 seperate flashdrives are indicated on each assigned LED,\nWhen a 3rd flashdrive is inserted, then both leds are used to indicate activity on the 3rd flashdrive,\nWhen a 4th flashdrive is inserted, the activity is divided between the LEDs(2 drives per LED),\n if 3 LEDs are assigned, 3 flashdrives are indicaded seperatly,\nWhen 4th flash drive is inserted then all 3 will indicate the 4th flashdrive\nif 4 LEDs assigned and each flash is independently indicated", font=("Helvetica", 14))
        label.pack(pady=20)

        def close_help():
            help_window.destroy()

        # Create buttons for the help window
        button_frame = tk.Frame(help_window)
        button_frame.pack(pady=10)

        next_button = tk.Button(button_frame, text="Next", command=show_help_image)
        next_button.pack(side="left", padx=10)

        exit_button = tk.Button(button_frame, text="Close", command=close_help)
        exit_button.pack(side="left", padx=10)

    help_button = tk.Button(button_frame, text="Help", command=show_help)
    help_button.pack(side="left", padx=10)

    # Function to validate GPIO pin entries
    def validate_gpio_pins():
        used_pins = {}
        for key, entry in gpio_entries.items():
            pin = entry.get().lstrip("0")
            status_key = key.replace("_pin", "_status")
            if status_key in switch_vars and switch_vars[status_key].get() == "on" and not pin:
                messagebox.showerror("Missing GPIO Pin", f"GPIO pin must be selected for {key.replace('_pin', '').replace('_', ' ').title()}.")
                return False
            if pin and (not pin.isdigit() or not (2 <= int(pin) <= 27)):
                messagebox.showerror("Invalid GPIO Pin", f"Invalid GPIO pin: {pin}. Please enter a number between 2 and 27, or leave it empty.")
                return False
            if pin in used_pins:
                messagebox.showerror("GPIO Pin Conflict", f"GPIO pin {pin} already in use.")
                return False
            if pin:
                used_pins[pin] = key

        return True

    def set_configuration():
        if not validate_gpio_pins():
            return
        new_config = {}
        for key, var in switch_vars.items():
            new_config[key] = var.get()
        for key, entry in gpio_entries.items():
            new_config[key] = entry.get()
        for key, var in trigger_vars.items():
            new_config[key] = var.get()
    
        # Function to update Amibian_LED_Starter.sh based on the new configuration
        def update_Amibian_LED_Starter_script(new_config):
            # Determine the new path to Amibian_LED_Starter.sh
            amibian_folder = find_amibian_folder()
            Amibian_LED_Starter_script_path = os.path.join(amibian_folder, "shells", "Amibian_LED_Starter.sh")

            with open(Amibian_LED_Starter_script_path, 'r') as file:
                lines = file.readlines()

            with open(Amibian_LED_Starter_script_path, 'w') as file:
                for line in lines:
                    if "scr_lock.py" in line:
                        new_script_path = os.path.join(amibian_folder, "Pythons", "scr_lock.py")
                        if new_config.get("scrlock_led_status") == "on":
                            file.write(f"/usr/bin/python3.11 {new_script_path} &\n")
                        else:
                            file.write(f"# /usr/bin/python3.11 {new_script_path} &\n")
                    elif "num_lock.py" in line:
                        new_script_path = os.path.join(amibian_folder, "Pythons", "num_lock.py")
                        if new_config.get("numlock_led_status") == "on":
                            file.write(f"/usr/bin/python3.11 {new_script_path} &\n")
                        else:
                            file.write(f"# /usr/bin/python3.11 {new_script_path} &\n")
                    elif "caps_lock.py" in line:
                        new_script_path = os.path.join(amibian_folder, "Pythons", "caps_lock.py")
                        if new_config.get("capslock_led_status") == "on":
                            file.write(f"/usr/bin/python3.11 {new_script_path} &\n")
                        else:
                            file.write(f"# /usr/bin/python3.11 {new_script_path} &\n")
                    elif "usb_activity.py" in line:
                        new_script_path = os.path.join(amibian_folder, "Pythons", "usb_activity.py")
                        if new_config.get("usb_activity_status") == "on":
                            file.write(f"/usr/bin/python3.11 {new_script_path} &\n")
                        else:
                            file.write(f"# /usr/bin/python3.11 {new_script_path} &\n")
                    else:
                        file.write(line)

        # Call the function to update Amibian_LED_Starter.sh with the new configuration
        update_Amibian_LED_Starter_script(new_config)


    
        # Update /boot/firmware/config.txt for Power LED, SD Activity LED, and Power Button
        config_txt_path = "/boot/firmware/config.txt"
        with open(config_txt_path, 'r') as file:
            lines = file.readlines()
    
        updated_lines = []
        for line in lines:
            if "dtoverlay=gpio-led,gpio=" in line and "label=powerled" in line:
                pin = new_config.get("power_led_pin", "")
                if new_config.get("power_led_status") == "on":
                    updated_lines.append(f"dtoverlay=gpio-led,gpio={pin},trigger=default-on,label=powerled\n")
                else:
                    updated_lines.append(f"#dtoverlay=gpio-led,gpio={pin},trigger=default-on,label=powerled\n")
            elif "dtparam=act_led_gpio=" in line:
                pin = new_config.get("activity_led_pin", "")
                if new_config.get("activity_led_status") == "on":
                    updated_lines.append(f"dtparam=act_led_gpio={pin}\n")
                else:
                    updated_lines.append(f"#dtparam=act_led_gpio={pin}\n")
            elif "dtoverlay=gpio-shutdown" in line:
                if new_config.get("power_button_status") == "on":
                    updated_lines.append("dtoverlay=gpio-shutdown\n")
                else:
                    updated_lines.append("#dtoverlay=gpio-shutdown\n")
            else:
                updated_lines.append(line)
                
        # Update USB Flashdrive Activity LED pin entries
        for i in range(1, 5):
            pin = new_config.get(f"usb_activity_pin{i}", "")
            updated_lines.append(f"usb_activity_pin{i}={pin}\n")
    
        # Use sudo to write the updated config.txt
        subprocess.run(["sudo", "sh", "-c", f"echo \"{''.join(updated_lines)}\" > {config_txt_path}"])

        # Manage the amibian.service
        if new_config.get("power_led_status") == "on":
            subprocess.run(["sudo", "systemctl", "daemon-reload"])
            subprocess.run(["sudo", "systemctl", "enable", "amibian.service"])
            subprocess.run(["sudo", "systemctl", "start", "amibian.service"])
        else:
            subprocess.run(["sudo", "systemctl", "daemon-reload"])
            subprocess.run(["sudo", "systemctl", "disable", "amibian.service"])
            subprocess.run(["sudo", "systemctl", "stop", "amibian.service"])
        
        # Write the updated configuration to amibian.configuration
        write_configuration(new_config)
        messagebox.showinfo("Configuration Set", "The GPIO configuration has been updated successfully.")

    # Create the "Set Config" button
    set_config_button = tk.Button(button_frame, text="Set Configuration", command=set_configuration)
    set_config_button.pack(side="right", padx=10)

# Function to close all windows except the main window
def close_all_windows():
    for window in root.winfo_children():
        if isinstance(window, tk.Toplevel):
            window.destroy()
    root.deiconify()

# Function to handle the "Paths" button click
def open_paths_menu(parent_window):
    parent_window.withdraw()
    paths_window = tk.Toplevel(root)
    paths_window.title("Paths Menu")
    paths_window.geometry("820x260")

    def close_paths_menu():
        paths_window.destroy()
        parent_window.deiconify()

    # Create a label for the Paths menu
    label = tk.Label(paths_window, text="Paths Menu", font=("Helvetica", 18))
    label.pack(pady=10)

    # Create a frame for the path inputs
    paths_frame = tk.Frame(paths_window)
    paths_frame.pack(pady=10)

    # Function to update paths based on the selected Amiberry path
    def update_paths(amiberry_path):
        amiberry_entry.delete(0, tk.END)
        amiberry_entry.insert(0, amiberry_path)
        config_entry.delete(0, tk.END)
        config_entry.insert(0, os.path.join(amiberry_path, "conf"))
        kickstarts_entry.delete(0, tk.END)
        kickstarts_entry.insert(0, os.path.join(amiberry_path, "kickstarts"))

    # Function to browse for a directory and update the corresponding entry
    def browse_directory(entry, config_key):
        directory = filedialog.askdirectory()
        if directory:
            entry.delete(0, tk.END)
            entry.insert(0, directory)
            if config_key == "amiberry_path":
                update_paths(directory)

    # Read the current configuration
    config = read_configuration()

    # Create the "Amiberry Folder" row
    amiberry_label = tk.Label(paths_frame, text="Path to Amiberry Folder:")
