    # Function to set the paths and update the necessary files
    def set_paths(amiberry_path, config_path, kickstart_path):
        # Update the configuration
        write_configuration({
            "amiberry_path": amiberry_path,
            "amiberry_config_path": config_path,
            "kickstart_path": kickstart_path
        })

        # Find the Amibian folder
        amibian_folder = find_amibian_folder()

        # Paths for the Python, shell scripts, and icons
        pythons_path = os.path.join(amibian_folder, "Pythons")
        shells_path = os.path.join(amibian_folder, "shells")
        icons_path = os.path.join(amibian_folder, "graphics", "misc_icons")

        # Update the Amibian_LED_Starter.sh file
        shell_script_path = os.path.join(shells_path, "Amibian_LED_Starter.sh")
        update_shell_script(shell_script_path, pythons_path)

        # Update the amibian.service file
        service_file_path = "/etc/systemd/system/amibian.service"
        update_service_file(service_file_path, pythons_path)

        # Update the amibian_LED.desktop file
        autostart_file_path = os.path.expanduser("~/.config/autostart/amibian_LED.desktop")
        update_autostart_file(autostart_file_path, shells_path)

        # Update the ram.desktop file on the system desktop
        ram_desktop_path = os.path.expanduser("~/Desktop/ram.desktop")
        update_ram_desktop_file(ram_desktop_path, shells_path, icons_path)

        # Reactivate the service to apply changes
        subprocess.run(["sudo", "systemctl", "daemon-reload"])
        subprocess.run(["sudo", "systemctl", "restart", "amibian.service"])

        messagebox.showinfo("Configuration Set", "The paths have been updated successfully.")

    # Function to update the shell script
    def update_shell_script(script_path, pythons_path):
        with open(script_path, "r") as file:
            lines = file.readlines()

        with open(script_path, "w") as file:
            for line in lines:
                if line.startswith("/usr/bin/python3.11"):
                    parts = line.split()
                    parts[1] = os.path.join(pythons_path, os.path.basename(parts[1]))
                    file.write(" ".join(parts) + "\n")
                else:
                    file.write(line)

    # Function to update the service file with sudo
    def update_service_file(service_path, pythons_path):
        with open(service_path, "r") as file:
            lines = file.readlines()

        updated_lines = []
        for line in lines:
            if line.startswith("ExecStart="):
                parts = line.split()
                parts[1] = os.path.join(pythons_path, os.path.basename(parts[1]))
                updated_lines.append(" ".join(parts) + "\n")
            elif line.startswith("WorkingDirectory="):
                updated_lines.append(f"WorkingDirectory={pythons_path}\n")
            else:
                updated_lines.append(line)

        subprocess.run(["sudo", "sh", "-c", f"echo \"{''.join(updated_lines)}\" > {service_path}"])

    # Function to update the autostart file
    def update_autostart_file(autostart_path, shells_path):
        with open(autostart_path, "r") as file:
            lines = file.readlines()

        with open(autostart_path, "w") as file:
            for line in lines:
                if line.startswith("Exec="):
                    parts = line.split("=")
                    parts[1] = os.path.join(shells_path, os.path.basename(parts[1].strip()))
                    file.write("=".join(parts) + "\n")
                else:
                    file.write(line)
                    
    # Function to update the ram.desktop file                
    def update_ram_desktop_file(ram_desktop_path, shells_path, icons_path):
        ram_disk_sh_path = os.path.join(shells_path, "ram_disk.sh")
        ram_disk_icon_path = os.path.join(icons_path, "ram_disk_2.png")

        # Read the current ram.desktop file
        with open(ram_desktop_path, 'r') as file:
            lines = file.readlines()

        # Update the Exec and Icon lines with the constructed paths
        with open(ram_desktop_path, 'w') as file:
            for line in lines:
                if line.startswith("Exec="):
                    line = f"Exec={ram_disk_sh_path} %F\n"
                elif line.startswith("Icon="):
                    line = f"Icon={ram_disk_icon_path}\n"
                file.write(line)

        # Set read and write permissions for owner, group, and others
        os.chmod(ram_desktop_path, stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR |
                                 stat.S_IRGRP | stat.S_IWGRP | stat.S_IXGRP |
                                 stat.S_IROTH | stat.S_IWOTH | stat.S_IXOTH)

